/* PD-CUATRECASAS-UNITARY-ACCOUNTABILITY-NEXUS-20261125-001 — preserve static fallback and the legacy LinkedIn panel */
(()=>{'use strict';const init=()=>{const root=document.querySelector('[data-pd-ccacm-436-nexus]');if(!root)return;const viewer=document.getElementById('ccacm-436-20261124-viewer');const insert=()=>{const panel=document.querySelector('[data-cuatrecasas-inigo-linkedin-record="20260306"]');if(!panel||!viewer)return false;const anchor=panel.querySelector('.cuatre-linkedin-message')||panel.querySelector('blockquote')||panel.querySelector('.cuatre-linkedin-captures');if(!anchor)return false;if(anchor.nextElementSibling!==viewer)anchor.insertAdjacentElement('afterend',viewer);if(location.hash==='#ccacm-436-20261124-viewer')requestAnimationFrame(()=>viewer.scrollIntoView({block:'start'}));return true;};if(!insert()){const obs=new MutationObserver(()=>{if(insert())obs.disconnect();});obs.observe(document.querySelector('main')||document.body,{childList:true,subtree:true});window.setTimeout(()=>obs.disconnect(),12000);}root.querySelectorAll('[data-nexus-filter]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.nexusFilter;root.querySelectorAll('[data-nexus-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));root.querySelectorAll('tr[data-nexus-types]').forEach(row=>row.hidden=key!=='all'&&!row.dataset.nexusTypes.split(' ').includes(key));}));const full=viewer?.querySelector('[data-nexus-fullscreen]');if(full){if(!viewer.requestFullscreen)full.hidden=true;else full.addEventListener('click',()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else viewer.requestFullscreen().catch(()=>{});});}};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();
